const assert = require('assert');
const { parseAmount } = require('../src/money');
const { checkout } = require('../src/checkout');
const { handle } = require('../src/server');

// Regression: prices with thousands separators ("1,299.00") made parseAmount crash
// with a TypeError, turning POST /checkout into a 500.
test('parses amounts with thousands separators', () => {
  assert.strictEqual(parseAmount('1,299.00'), 129900);
  assert.strictEqual(parseAmount('2,450.50'), 245050);
  assert.strictEqual(parseAmount('1,005.99'), 100599);
  assert.strictEqual(parseAmount('1,234,567.8'), 123456780);
});
test('rejects malformed amounts with a clear error', () => {
  for (const bad of ['abc', '', '1,29.00', '12,3456', '1.234', ',100']) {
    assert.throws(() => parseAmount(bad), { message: `Invalid amount: ${bad}` });
  }
});
test('checkout totals items priced over 1,000', () => {
  assert.deepStrictEqual(checkout({ id: 'o2', items: [{ sku: 'P-76', price: '1,299.00', qty: 2 }] }), { orderId: 'o2', totalCents: 259800 });
});
test('POST /checkout with a thousands-separated price returns 200', () => {
  const origLog = console.log;
  console.log = () => {};
  try {
    const res = handle({ method: 'POST', path: '/checkout', body: { id: 'o3', items: [{ sku: 'P-79', price: '2,450.50', qty: 1 }] } });
    assert.strictEqual(res.status, 200);
    assert.strictEqual(res.body.totalCents, 245050);
  } finally {
    console.log = origLog;
  }
});

